'use strict';
(()=>{
const $=id=>document.getElementById(id),frame=$('viewer');let timeout;
const sections={
 a1:{title:'Quelle, Energie, Richtung und Strahlenart',prompt:'Prüfen Sie die fehlerhafte Erklärung aus A1. Nutzen Sie dafür die drei Ansichten und verknüpfen Sie anschließend die Bauteile miteinander.',response:'Korrigieren Sie die Erklärung aus A1 in drei bis vier Sätzen. Unterscheiden Sie Teilchenquelle, Energiezufuhr, Umlenkung und Photonenerzeugung.',steps:[
 {label:'1 · Quelle & Energie',url:'view1.html',observe:'Verfolgen Sie den türkis markierten Elektronenweg und den violetten Weg der HF-Energie. Wo beginnen die beiden Wege, und wo treffen sie zusammen?',legend:'Türkis: Elektronen · Violett: HF-Energie',limit:'Die Beschleunigungsstruktur ist als Schnitt dargestellt. Flugzeiten und Teilchenzahlen sind vereinfacht.',help:'HF bedeutet Hochfrequenz. Das elektrische HF-Feld überträgt Energie auf Elektronen. Die Elektronenkanone und die HF-Quelle erfüllen unterschiedliche Aufgaben.'},
 {label:'2 · Umlenkung',url:'view2.html?clip=bend',observe:'Verfolgen Sie die Elektronen durch die Magnetbereiche bis zum Target. Welche Veränderung der Bahn können Sie sehen?',legend:'Türkis: Elektronen · Blau: Magnetbereiche',limit:'Die gezeigte Magnetanordnung ist ein Beispiel. Die Bahn ist keine berechnete Gerätebahn.',help:'Ein statisches Magnetfeld kann die Richtung der Elektronen ändern. Es erhöht ihre kinetische Energie dabei nicht. Erinnern Sie sich an die Energiezufuhr in der vorherigen Ansicht.'},
 {label:'3 · Target',url:'view2.html?clip=target',observe:'Achten Sie auf die Strahlung vor und hinter dem Target. An welcher Stelle beginnen die gelben Spuren?',legend:'Türkis: Elektronen · Gelb: Photonen',limit:'Nur ausgewählte Teilchenspuren sind sichtbar. Die Darstellung bedeutet nicht, dass jedes Elektron vollständig zu einem Photon wird.',help:'Wenn Elektronen im Target abgebremst und abgelenkt werden, kann Bremsstrahlung entstehen. Ein Teil der Energie wird außerdem als Wärme im Material deponiert.'}
 ]},
 a2:{title:'Feldöffnung und Dosis auseinanderhalten',prompt:'Spielen Sie die Anpassung der Lamellen ab. Vergleichen Sie anschließend mit den beiden Schaltflächen die rechteckige und die angepasste Öffnung.',response:'Bearbeiten Sie A2: Erklären Sie den Nutzen der angepassten Öffnung. Beurteilen Sie die Aussage zur Tumordosis und Organschonung und nennen Sie zwei zusätzlich benötigte Informationen.',steps:[
 {url:'view2.html?clip=mlc',observe:'Vergleichen Sie, wie viel Fläche außerhalb der gestrichelten Zielkontur in der Öffnung liegt. Welche Information über die Bestrahlung erhalten Sie aus diesem Bild – und welche fehlt?',legend:'Gestrichelt: Zielprojektion · Gelb: direkte Strahlwege bzw. geometrische Öffnung · Blaue Zeile: Schnitt links',limit:'Die Lamellen bewegen sich hier bei ausgeschaltetem Strahl. Danach folgt eine geometrische Feldvorschau; Streuung, Transmission und Gewebedosis werden nicht berechnet.',help:'Die rechte Ansicht zeigt den Blick entlang einer Einstrahlrichtung. Eine Feldöffnung ist eine geometrische Information. Überlegen Sie, welche Information Sie über das gesamte Zielvolumen und das umgebende Gewebe benötigen.'}
 ]},
 a3:{title:'Was belegt das Monitorsignal?',prompt:'Spielen Sie den Ablauf bis zum Abschalten ab. Prüfen Sie damit die Aussage aus A3: „Der richtige Patient wurde an der richtigen Stelle mit der richtigen Dosis behandelt.“',response:'Bearbeiten Sie A3: Erklären Sie, was das Signal belegt und was damit offenbleibt. Wählen Sie zwei zusätzliche Prüfbereiche und beschreiben Sie, was dort geprüft werden muss.',steps:[
 {url:'view2.html?clip=monitor',observe:'Suchen Sie das Monitorsystem im Strahlkopf. Beobachten Sie die Anzeige und den Strahl beim Erreichen des Sollwerts. Wo entsteht das Messsignal?',legend:'Gelb: Photonen · Anzeige: frei gewählter Demo-Monitorwert',limit:'100 % bedeutet hier nur: Der Demo-Sollwert ist erreicht. Es ist weder eine klinische MU-Zahl noch eine Dosisangabe für den Patienten.',help:'Das Monitorsystem erfasst die Strahlabgabe im Kopf. Für Ihre Beurteilung können Sie außerdem an Patientenzuordnung, Körperposition und Zuordnung des Behandlungsplans denken.'}
 ]}
};
function view(task,index){const section=sections[task],step=section.steps[index];$('observe').textContent=step.observe;$('legend').textContent=step.legend;$('limit').textContent=step.limit;$('helpText').textContent=step.help;$('help').open=false;
 document.querySelectorAll('#steps button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));
 frame.contentWindow?.postMessage({type:'lesson-pause'},location.origin);frame.style.height='500px';frame.title=section.title+(step.label?' · '+step.label:'');frame.src=step.url;$('directView').href=step.url;$('mediaError').hidden=true;clearTimeout(timeout);timeout=setTimeout(()=>$('mediaError').hidden=false,12000);
}
function route(){const task=location.hash.slice(1).toLowerCase() in sections?location.hash.slice(1).toLowerCase():'a1',s=sections[task];$('taskLabel').textContent=task.toUpperCase()+' · ARBEITSBLATT AB01';$('taskTitle').textContent=s.title;$('taskPrompt').textContent=s.prompt;$('response').textContent=s.response;document.querySelectorAll('[data-task]').forEach(a=>{if(a.dataset.task===task)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('steps').replaceChildren();$('steps').hidden=s.steps.length===1;s.steps.forEach((step,i)=>{if(!step.label)return;const b=document.createElement('button');b.type='button';b.textContent=step.label;b.onclick=()=>view(task,i);$('steps').append(b);});view(task,0);}
window.addEventListener('hashchange',route);window.addEventListener('message',e=>{if(e.source!==frame.contentWindow||e.origin!==location.origin||e.data?.type!=='lesson-size')return;const h=Number(e.data.height);if(Number.isFinite(h)&&h>100&&h<2500){frame.style.height=Math.ceil(h)+'px';$('mediaError').hidden=true;clearTimeout(timeout);}});route();
})();
